head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > P > keepRowPosition]<br/>set 계열의 메소드로 DataList 모듈에 데이터가 추가될때 선택된 Row 의 인덱스를 유지합니다.",
    "validation" : [
        "set 계열 이외의 메소드(insert 계열, setRow 계열 등) 실행 시 true 로 동작합니다.",
        "미설정 또는 true 설정 시 set 계열의 메소드로 데이터가 추가될때 DataList 모듈의 선택 Row 인덱스가 유지됩니다.",
        "false 설정 시 set 계열의 메소드로 데이터가 추가될때 DataList 모듈의 선택 Row 인덱스가 null 로 설정됩니다.",
        "GridView 의 syncRowPositionOption 속성값에 관계없이 GridView 에 null 값이 반영되지 않습니다.",
        "keepRowPosition=false 일때 DataList 모듈의 선택 Row 인덱스가 null 로 설정되어도 onbeforerowpositionchange, onrowpositionchange 이벤트가 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // 조건 설정       
    let properties = {
        keepRowPosition : con_keepRowPosition.getText(),
    };

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList(cList);

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true" focusMode="row" syncRowPositionOption="style"', '', 'gridView1');    

    scwin.btn_setRowPosition_onclick();
}   



scwin.btn_getRowPosition_onclick = function (e) {
    let rtn = target1.getRowPosition();
	wf_body_bottom.getObj("scwin").setReturnValue("target1 rowposition : " + rtn);

    rtn = gridView1.getFocusedRowIndex();
    wf_body_bottom.getObj("scwin").setReturnValue("gridView1 rowposition : " + rtn);
};



scwin.btn_setRowPosition_onclick = function (e) {
	target1.setRowPosition(2);
};




scwin.btn_setJSON_onclick = function (e) {   
    let jsonData = [
        {col1:"setcol1",col2:"setcol2",col3:"setcol3",col4:"setcol4"},
    ];

    target1.setJSON(jsonData, true);

    scwin.btn_getRowPosition_onclick();
};



scwin.btn_insertJSON_onclick = function (e) {
	target1.insertJSON(0, [{col1:"insert1",col2:"insert2",col3:"insert3",col4:"insert4"}]);

    scwin.btn_getRowPosition_onclick();
};



scwin.target1_onbeforerowpositionchange = function (info) {
	wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforerowpositionchange=====");
};



scwin.target1_onrowpositionchange = function (info) {
	wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onrowpositionchange=====");
};



scwin.gridView1_oncellclick = function (rowIndex, columnIndex, columnId) {
	scwin.btn_getRowPosition_onclick();
};
